const {chromium}=require('playwright'),fs=require('fs'),path=require('path');
(async()=>{const out=process.env.OUTPUT_DIR;fs.mkdirSync(out,{recursive:true});const b=await chromium.launch({headless:true});const p=await b.newPage();await p.goto(process.env.PREVIEW_ROOT+'/leetcode/675/');const records=[];for(const width of [320,390]){await p.setViewportSize({width,height:950});for(const lang of ['en','zh']){await p.locator('[data-lang='+lang+']').click();for(let index=0;index<6;index++){await p.selectOption('#preset',String(index));const data=await p.locator('#preset').evaluate(el=>{const s=getComputedStyle(el),ctx=document.createElement('canvas').getContext('2d');ctx.font=s.font;const label=el.selectedOptions[0].textContent;return {label,font:s.font,width:el.clientWidth,paddingLeft:parseFloat(s.paddingLeft),paddingRight:parseFloat(s.paddingRight),arrowAllowance:0,textWidth:ctx.measureText(label).width};});data.available=data.width-data.paddingLeft-data.paddingRight-data.arrowAllowance;data.fits=data.textWidth<=data.available;records.push({viewportWidth:width,lang,index,...data});if(!data.fits||index===4)await p.locator('#preset').screenshot({path:path.join(out,`${lang}-${width}-${index}.png`)});}}}const result={platform:process.platform,browser:b.version(),control:'#preset',measurement:'Necessary text-content fit only; zero arrow reservation is conservative for detecting definite overflow, not sufficient to prove native-arrow clearance. Inspect screenshots.',records,failures:records.filter(x=>!x.fits)};fs.writeFileSync(path.join(out,'selected-label-results.json'),JSON.stringify(result,null,2)+'\n');await b.close();console.log(JSON.stringify({records:records.length,failures:result.failures}));if(result.failures.length)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1});
